/* Differential test: AOT vs slice IR vs predecoded container.
 *
 * Corpus: tests/ir_corpus.h (self-authored i386 bytes, no game data).
 * AOT:    tests/ir_aot_fixture.c, generated by the real staged/lift.py.
 * IR:     source/ir_decode.c + source/ir_exec.c decoding the corpus at runtime.
 * Cont.:  the same corpus packed ahead of time by tests/ir_container_pack.c
 *         through the real C decoder.
 *
 * Every supported function runs from identical CPU/guest memory three times
 * (AOT, IR, container) and the full CPU struct, result and guest writes are
 * compared. Unsupported entries must fault explicitly, and container runs must
 * never touch the runtime decoder (stats.redecodes == 0 and the decode-cache
 * block counter does not move).
 */
#include "ir_container.h"
#include "ir_corpus.h"
#include "ir_core.h"
#include "guest.h"
#include "rt_table.h"

#include <setjmp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

extern const FnEntry g_fn_table_ira[];
extern const unsigned g_fn_count_ira;

#define IN_ADDR   0x60000000u
#define OUT_ADDR  0x60001000u
#define SCR_ADDR  0x60002000u
#define SCR2_ADDR 0x60004000u
#define MAT_ADDR  0x60006000u
#define STACK_TOP 0x60018000u
#define TEB_ADDR  0x60020000u

static GuestMemory mem;
static FnEntry aot[128];
static unsigned naot;
static CPU ca, ci, cc;
static N3dsIrc *irc;
static int g_mode; /* 0: AOT/IR, 1: container-first */
static jmp_buf *g_jb;
static char g_fault[256];

/* --------------------------------------------------------------- stubs */

void *n3ds_guest_ptr(uint32_t addr, size_t bytes) {
    void *p = guest_ptr(&mem, addr, bytes);
    if (!p) rt_unimpl(NULL, addr, "unmapped guest memory");
    return p;
}

void rt_unimpl(CPU *c, uint32_t addr, const char *what) {
    (void)c;
    snprintf(g_fault, sizeof g_fault, "Guest fault at %08lx: %s",
             (unsigned long)addr, what ? what : "unknown");
    if (g_jb) longjmp(*g_jb, 1);
    fprintf(stderr, "%s\n", g_fault);
    abort();
}

void rt_int3(CPU *c, uint32_t addr) { rt_unimpl(c, addr, "int3"); }

void rt_cpuid(CPU *c, uint32_t *a, uint32_t *b, uint32_t *cc_, uint32_t *d) {
    (void)c;
    uint32_t leaf = *a;
    *a = *b = *cc_ = *d = 0;
    if (!leaf) {
        *a = 1;
        memcpy(b, "Genu", 4);
        memcpy(d, "ineI", 4);
        memcpy(cc_, "ntel", 4);
    } else if (leaf == 1) {
        *a = 0x00000f29u;
        *d = (1u << 0) | (1u << 4) | (1u << 15) | (1u << 23) | (1u << 25) | (1u << 26);
    }
}

uint64_t rt_rdtsc(void) { return 1; }

static const FnEntry *aot_find(uint32_t addr) {
    unsigned lo = 0, hi = naot;
    while (lo < hi) {
        unsigned mid = lo + (hi - lo) / 2;
        if (aot[mid].addr < addr) lo = mid + 1;
        else hi = mid;
    }
    return lo < naot && aot[lo].addr == addr ? &aot[lo] : NULL;
}

int n3ds_rt_dispatch(CPU *c, uint32_t addr) {
    if (g_mode == 1 && irc) {
        int rc = n3ds_irc_exec_status(irc, c, addr, 0);
        if (rc == N3DS_IRC_TIER_CONTAINER) return 0;
        if (rc != N3DS_IRC_ERR_NOT_FOUND && rc != N3DS_IRC_ERR_UNDECODED) return -1;
    }
    const FnEntry *e = aot_find(addr);
    if (e) { e->fn(c); return 0; }
    if (n3ds_ir_has(addr)) { n3ds_ir_call(c, addr); return 0; }
    return -1;
}

void rt_call(CPU *c, uint32_t addr) {
    if (n3ds_rt_dispatch(c, addr))
        rt_unimpl(c, addr, "unknown function/import");
}

void rt_call_ic(CPU *c, uint32_t addr, const FnEntry **cache) {
    if (g_mode == 1 && irc) {
        int rc = n3ds_irc_exec_status(irc, c, addr, 0);
        if (rc == N3DS_IRC_TIER_CONTAINER) { *cache = NULL; return; }
    }
    const FnEntry *e = aot_find(addr);
    if (e) { *cache = e; e->fn(c); return; }
    *cache = NULL;
    if (n3ds_ir_has(addr)) { n3ds_ir_call(c, addr); return; }
    rt_unimpl(c, addr, "unknown indirect function");
}

/* --------------------------------------------------------------- state */

static void init_cpu(CPU *c) {
    memset(c, 0, sizeof *c);
    c->r[4] = STACK_TOP;
    c->fs_base = TEB_ADDR;
    c->fpu_cw = 0x37f;
    c->mxcsr = 0x1f80;
}

static void put32(uint32_t a, uint32_t v) { M32(a) = v; }

static uint32_t rnd_state;
static uint32_t rnd(void) {
    rnd_state ^= rnd_state << 13;
    rnd_state ^= rnd_state >> 17;
    rnd_state ^= rnd_state << 5;
    return rnd_state;
}

static void fill_state(uint32_t seed, const char *name, uint32_t call_target) {
    rnd_state = seed ? seed : 1;
    for (uint32_t k = 0; k < 16; ++k) {
        uint32_t v = rnd();
        if (k % 5 == 0) v = 0;
        if (k % 7 == 0) v = 0x80000000u;
        if (k % 11 == 0) v = 0xffffffffu;
        put32(IN_ADDR + 4 * k, v);
    }
    for (uint32_t k = 0; k < 128; ++k) {
        *(uint8_t *)n3ds_guest_ptr(SCR_ADDR + k, 1) = (uint8_t)(0x11 + k);
        *(uint8_t *)n3ds_guest_ptr(SCR2_ADDR + k, 1) = (uint8_t)(0x80 + k);
        *(uint8_t *)n3ds_guest_ptr(OUT_ADDR + k, 1) = 0;
    }
    for (uint32_t k = 0; k < 48; ++k) {
        float f = (float)((int32_t)(rnd() % 2001) - 1000) / 8.0f;
        memcpy(n3ds_guest_ptr(MAT_ADDR + 4 * k, 4), &f, 4);
    }
    put32(IN_ADDR + 8, call_target);
    put32(IN_ADDR + 16, SCR_ADDR);
    put32(IN_ADDR + 20, SCR2_ADDR);
    put32(IN_ADDR + 24, 0xdeadbe00u);
    (void)name;
}

typedef enum { TIER_AOT = 0, TIER_IR = 1, TIER_CONTAINER = 2 } Tier;

static int run_tier(CPU *c, const IrCorpusFn *fn, Tier tier, uint32_t seed,
                    uint32_t call_target, uint32_t *res, char *fault_copy,
                    uint32_t end_override) {
    uint32_t end = end_override ? end_override : fn->end;
    uint32_t addr = fn->addr;
    init_cpu(c);
    fill_state(seed, fn->name, call_target);
    uint32_t args[2] = {IN_ADDR, OUT_ADDR};
    uint32_t sp = c->r[4];
    uint32_t frame = 3 * 4;
    uint32_t base = sp - frame;
    if (!guest_ptr(&mem, base, frame)) return -99;
    M32(base) = 0xffffffffu;
    M32(base + 4) = args[0];
    M32(base + 8) = args[1];
    c->r[4] = base;

    jmp_buf jb;
    jmp_buf *old = g_jb;
    g_jb = &jb;
    g_fault[0] = 0;
    int trapped = setjmp(jb);
    int rc;
    if (trapped) {
        g_jb = old;
        g_mode = 0;
        if (tier == TIER_CONTAINER) n3ds_irc_recover(irc);
        c->r[4] = sp;
        if (fault_copy) snprintf(fault_copy, 256, "%s", g_fault);
        return -2;
    }
    g_mode = tier == TIER_CONTAINER;
    if (tier == TIER_AOT) {
        const FnEntry *e = aot_find(addr);
        if (!e) { g_jb = old; c->r[4] = sp; return -1; }
        e->fn(c);
        rc = 0;
    } else if (tier == TIER_IR) {
        n3ds_ir_run(c, addr, end);
        rc = 0;
    } else {
        rc = n3ds_irc_exec_forced(irc, c, addr);
        rc = rc == N3DS_IRC_TIER_CONTAINER ? 0 : -3;
    }
    g_jb = old;
    g_mode = 0;
    int ok = c->r[4] == base + 4 || c->r[4] == sp;
    c->r[4] = sp;
    if (!ok) return -4;
    if (res) *res = c->r[0];
    if (fault_copy) fault_copy[0] = 0;
    return rc;
}

static int show_cpu_diff(const CPU *a, const CPU *b) {
    for (unsigned k = 0; k < 8; ++k)
        if (a->r[k] != b->r[k]) {
            printf("    r[%u] %08x vs %08x\n", k, a->r[k], b->r[k]);
            return 1;
        }
    if (a->df != b->df || a->eflags_hi != b->eflags_hi || a->top != b->top ||
        a->c0 != b->c0 || a->c1 != b->c1 || a->c2 != b->c2 || a->c3 != b->c3)
        return 1;
    for (unsigned k = 0; k < 8; ++k)
        if (memcmp(&a->st[k], &b->st[k], sizeof a->st[k])) return 1;
    return memcmp(a, b, sizeof *a) != 0;
}

static const IrCorpusFn *find_fn(const char *name) {
    for (unsigned i = 0; i < IR_CORPUS_FN_COUNT; ++i)
        if (!strcmp(ir_corpus_fns[i].name, name)) return &ir_corpus_fns[i];
    return NULL;
}

typedef struct {
    uint8_t out[128], scr[256], scr2[256], mat[192];
} Snapshot;

static void snap(Snapshot *s) {
    memcpy(s->out, n3ds_guest_ptr(OUT_ADDR, sizeof s->out), sizeof s->out);
    memcpy(s->scr, n3ds_guest_ptr(SCR_ADDR, sizeof s->scr), sizeof s->scr);
    memcpy(s->scr2, n3ds_guest_ptr(SCR2_ADDR, sizeof s->scr2), sizeof s->scr2);
    memcpy(s->mat, n3ds_guest_ptr(MAT_ADDR, sizeof s->mat), sizeof s->mat);
}

static int snap_diff(const Snapshot *s) {
    return memcmp(s->out, n3ds_guest_ptr(OUT_ADDR, sizeof s->out), sizeof s->out) ||
           memcmp(s->scr, n3ds_guest_ptr(SCR_ADDR, sizeof s->scr), sizeof s->scr) ||
           memcmp(s->scr2, n3ds_guest_ptr(SCR2_ADDR, sizeof s->scr2), sizeof s->scr2) ||
           memcmp(s->mat, n3ds_guest_ptr(MAT_ADDR, sizeof s->mat), sizeof s->mat);
}

static int equiv_function(const IrCorpusFn *fn, unsigned variant, int compare_aot) {
    uint32_t call_target = IR_CALLEE_ADDR;
    uint32_t seed = 0x9e3779b9u ^ (variant * 0x85ebca6bu);
    uint32_t ra = 0, ri = 0, rc = 0;
    char fault[256] = "";
    int rca = -1, rci, rcc;
    Snapshot sa;

    if (compare_aot) {
        rca = run_tier(&ca, fn, TIER_AOT, seed, call_target, &ra, fault, 0);
        if (rca != 0) {
            printf("  FAIL %s: AOT rc=%d fault='%s'\n", fn->name, rca, fault);
            return 1;
        }
        snap(&sa);
    }

    rcc = run_tier(&cc, fn, TIER_CONTAINER, seed, call_target, &rc, fault, 0);
    if (rcc != 0) {
        printf("  FAIL %s: container rc=%d fault='%s'\n", fn->name, rcc, fault);
        return 1;
    }
    if (compare_aot && snap_diff(&sa)) {
        printf("  FAIL %s: container guest memory differs from AOT\n", fn->name);
        return 1;
    }

    rci = run_tier(&ci, fn, TIER_IR, seed, call_target, &ri, fault, 0);
    if (rci != 0) {
        printf("  FAIL %s: IR rc=%d fault='%s'\n", fn->name, rci, fault);
        return 1;
    }
    if (rc != ri || show_cpu_diff(&cc, &ci)) {
        printf("  FAIL %s: container/IR result %08x/%08x\n", fn->name, rc, ri);
        return 1;
    }
    if (compare_aot && (rc != ra || show_cpu_diff(&ca, &cc))) {
        printf("  FAIL %s: container/AOT result %08x/%08x\n", fn->name, rc, ra);
        return 1;
    }
    if (compare_aot && !snap_diff(&sa)) {
        /* snapshot was already validated against the container above */
    }
    return 0;
}

/* --------------------------------------------------------------- cases */

static int test_unsupported(void) {
    N3dsIrcEntry e;
    if (n3ds_irc_lookup(irc, IR_UNSUPPORTED_ADDR, &e) != N3DS_IRC_OK) {
        printf("  FAIL unsupported: entry missing\n");
        return 1;
    }
    if ((e.flags & N3DS_IRC_FN_DECODED) || e.decode_status != N3DS_IRC_DEC_UNSUPPORTED) {
        printf("  FAIL unsupported: flags=%x status=%u\n", e.flags, e.decode_status);
        return 1;
    }
    IrCorpusFn fn = {IR_UNSUPPORTED_ADDR, IR_UNSUPPORTED_END, "unsupported"};
    char fault[256] = "";
    int rc = run_tier(&cc, &fn, TIER_CONTAINER, 0xabcdef01u, 0, NULL, fault, 0);
    if (rc != -2) {
        printf("  FAIL unsupported: did not fault (rc=%d)\n", rc);
        return 1;
    }
    if (!strstr(fault, "not decoded") || !strstr(fault, "unsupported opcode")) {
        printf("  FAIL unsupported: fault text '%s'\n", fault);
        return 1;
    }
    printf("  ok unsupported: %s\n", fault);
    return 0;
}

static int pred_calls;
static uint32_t pred_target;

static int aot_pred(void *user, uint32_t addr) {
    (void)user;
    pred_calls++;
    return addr == pred_target;
}

static int test_aot_precedence(void) {
    const IrCorpusFn *fn = &ir_corpus_fns[0];
    pred_target = fn->addr;
    pred_calls = 0;
    n3ds_irc_set_aot_predicate(irc, aot_pred, NULL);
    N3dsIrcStats before, after;
    n3ds_irc_stats(irc, &before);
    init_cpu(&cc);
    int rc = n3ds_irc_exec(irc, &cc, fn->addr);
    n3ds_irc_stats(irc, &after);
    if (rc != N3DS_IRC_TIER_AOT) {
        printf("  FAIL aot precedence: rc=%d\n", rc);
        return 1;
    }
    if (pred_calls != 1 || after.aot_preempted != before.aot_preempted + 1 ||
        after.execs != before.execs || after.loads != before.loads) {
        printf("  FAIL aot precedence: pred=%d preempt=%llu execs=%llu loads=%llu\n",
               pred_calls, (unsigned long long)after.aot_preempted,
               (unsigned long long)after.execs, (unsigned long long)after.loads);
        return 1;
    }
    /* Forced container execution still works for the same address; this proves
     * the overlay is a dispatch decision, not a missing record. */
    IrCorpusFn local = *fn;
    uint32_t r = 0;
    char fault[256] = "";
    int rcc = run_tier(&cc, &local, TIER_CONTAINER, 0x1234u, IR_CALLEE_ADDR, &r, fault, 0);
    if (rcc) { printf("  FAIL aot precedence: forced container rc=%d\n", rcc); return 1; }
    n3ds_irc_set_aot_predicate(irc, NULL, NULL);
    printf("  ok aot precedence: AOT preempted without a container load\n");
    return 0;
}

static int test_unknown(void) {
    N3dsIrcEntry e;
    if (n3ds_irc_lookup(irc, 0x12345678u, &e) != N3DS_IRC_ERR_NOT_FOUND) {
        printf("  FAIL unknown lookup\n");
        return 1;
    }
    init_cpu(&cc);
    int rc = n3ds_irc_exec_status(irc, &cc, 0x12345678u, 0);
    if (rc != N3DS_IRC_ERR_NOT_FOUND) {
        printf("  FAIL unknown exec status %d\n", rc);
        return 1;
    }
    printf("  ok unknown: explicit not-found\n");
    return 0;
}

static int test_no_redecode(void) {
    IrCacheStats before, after;
    n3ds_ir_cache_stats(&before);
    const IrCorpusFn *fn = find_fn("memops");
    if (!fn) return 1;
    IrCorpusFn local = *fn;
    uint32_t r = 0;
    char fault[256];
    if (run_tier(&cc, &local, TIER_CONTAINER, 0x77u, IR_CALLEE_ADDR, &r, fault, 0)) return 1;
    n3ds_ir_cache_stats(&after);
    N3dsIrcStats st;
    n3ds_irc_stats(irc, &st);
    if (after.blocks != before.blocks || st.redecodes != 0 || st.block_hits == 0) {
        printf("  FAIL no-redecode: IR blocks %llu -> %llu, redecodes %llu, block_hits %llu\n",
               (unsigned long long)before.blocks, (unsigned long long)after.blocks,
               (unsigned long long)st.redecodes, (unsigned long long)st.block_hits);
        return 1;
    }
    printf("  ok no-redecode: container executed without decoding\n");
    return 0;
}

/* ---------------------------------------------------------------- main */

int main(int argc, char **argv) {
    setvbuf(stdout, NULL, _IONBF, 0);
    if (argc < 2) {
        fprintf(stderr, "usage: %s container.irc\n", argv[0]);
        return 2;
    }
    guest_init(&mem, 64u << 20);
    if (guest_map(&mem, IR_CORPUS_BASE, 0x1000) ||
        guest_map(&mem, IN_ADDR, 0x1000) || guest_map(&mem, OUT_ADDR, 0x1000) ||
        guest_map(&mem, SCR_ADDR, 0x2000) || guest_map(&mem, SCR2_ADDR, 0x2000) ||
        guest_map(&mem, MAT_ADDR, 0x1000) || guest_map(&mem, 0x60010000u, 0x10000) ||
        guest_map(&mem, TEB_ADDR, 0x1000)) {
        printf("map failed\n");
        return 2;
    }
    void *code = guest_ptr(&mem, IR_CORPUS_BASE, IR_CORPUS_BYTES);
    if (!code) { printf("code map failed\n"); return 2; }
    memcpy(code, ir_corpus_image, IR_CORPUS_BYTES);

    naot = 0;
    for (unsigned i = 0; i < g_fn_count_ira && naot < sizeof aot / sizeof aot[0]; ++i)
        aot[naot++] = g_fn_table_ira[i];
    for (unsigned i = 1; i < naot; ++i) {
        FnEntry e = aot[i];
        unsigned j = i;
        while (j && aot[j - 1].addr > e.addr) { aot[j] = aot[j - 1]; --j; }
        aot[j] = e;
    }

    IrFnEntry irtab[128];
    unsigned nir = 0;
    for (unsigned i = 0; i < IR_CORPUS_FN_COUNT && nir < 120; ++i)
        irtab[nir++] = (IrFnEntry){ir_corpus_fns[i].addr, ir_corpus_fns[i].end};
    irtab[nir++] = (IrFnEntry){IR_HELPER_ADDR, IR_HELPER_END};
    irtab[nir++] = (IrFnEntry){IR_CALLEE_ADDR, IR_HELPER_ADDR};
    for (unsigned i = 1; i < nir; ++i) {
        IrFnEntry e = irtab[i];
        unsigned j = i;
        while (j && irtab[j - 1].addr > e.addr) { irtab[j] = irtab[j - 1]; --j; }
        irtab[j] = e;
    }
    if (n3ds_ir_bind(irtab, nir)) { printf("bind IR failed\n"); return 2; }
    if (n3ds_ir_cache_init(1u << 20)) { printf("cache init failed\n"); return 2; }

    int status = 0;
    irc = n3ds_irc_open_ex(argv[1], &status);
    if (!irc) {
        printf("container open failed: %s (%d)\n", n3ds_irc_strstatus(status), status);
        return 2;
    }
    if (n3ds_irc_cache_init(irc, 4u << 20, 64) != N3DS_IRC_OK) {
        printf("container cache init failed\n");
        return 2;
    }

    int fail = 0;
    printf("container equiv: %u functions, %u AOT\n",
           n3ds_irc_function_count(irc), naot);

    for (unsigned f = 0; f < IR_CORPUS_FN_COUNT; ++f) {
        const IrCorpusFn *fn = &ir_corpus_fns[f];
        if (!strcmp(fn->name, "pilotcall")) {
            /* The pilot D3DX fixture is a separate generated artefact; this
             * standalone test has no pilot image to call. */
            printf("  skip %-10s (pilot fixture not linked)\n", fn->name);
            continue;
        }
        int is_cmc = !strcmp(fn->name, "cmc");
        int has_aot = aot_find(fn->addr) != NULL;
        for (unsigned v = 0; v < 4; ++v) {
            /* cmc has a known AOT miscompile; compare container with IR only. */
            if (equiv_function(fn, v, has_aot && !is_cmc)) { fail = 1; goto done; }
        }
        printf("  ok %-10s 4 inputs (%s%s)\n", fn->name,
               has_aot ? "AOT" : "IR", has_aot && !is_cmc ? "+container" : "+IR+container");
    }
    if (test_unsupported()) fail = 1;
    if (test_aot_precedence()) fail = 1;
    if (test_unknown()) fail = 1;
    if (test_no_redecode()) fail = 1;

    N3dsIrcStats st;
    n3ds_irc_stats(irc, &st);
    printf("stats: load %llu (%llu B, %llu ns), hits %llu misses %llu, "
           "evictions %llu, invalid %llu, execs %llu, redecodes %llu\n",
           (unsigned long long)st.loads, (unsigned long long)st.load_bytes,
           (unsigned long long)st.load_ns, (unsigned long long)st.cache_hits,
           (unsigned long long)st.cache_misses, (unsigned long long)st.evictions,
           (unsigned long long)st.invalid_entries, (unsigned long long)st.execs,
           (unsigned long long)st.redecodes);
    if (st.redecodes != 0) fail = 1;

done:
    n3ds_irc_close(irc);
    guest_destroy(&mem);
    if (!fail) printf("IR container equivalence PASS\n");
    return fail ? 1 : 0;
}
